function nativeEvidence(){const results=[];function walk(root){for(const file of fs.readdirSync(root,{withFileTypes:true})){const full=path.join(root,file.name);if(file.isDirectory())walk(full);else if(file.name.endsWith('.jsonl')){for(const line of fs.readFileSync(full,'utf8').split('\n').filter(Boolean)){const entry=JSON.parse(line),message=entry.message;if(message?.role!=='toolResult'||message.toolName!=='education_verify_material_quote')continue;for(const part of message.content||[]){if(part.type!=='text')continue;try{const value=JSON.parse(part.text);if(value.schemaVersion==='xiaozhi.education.quote.v1')results.push({found:value.found,mode:value.mode,version:value.version,offset:value.offset,teacherConfirmed:value.teacherConfirmed,originalPageLocated:value.originalPageLocated});}catch{}}}}}}walk(path.join(data,'xiaozhi-pi'));return results;}
