 const complete=await snapshot();assert.equal(complete.projection.turns.at(-1).status,'completed');assert.equal(complete.limitsEnforced,false);const persisted=readFacts().assistant,metadata=JSON.parse(persisted.metadata_json);assert(persisted.content.replace(/\s+/g,'').includes(evidence));assert(persisted.content.includes('直角三角形'));
 const publicItems=metadata.publicItems,searchItems=publicItems.filter(item=>item.kind==='tool'&&item.label==='查找资料正文'&&item.status==='completed');assert(searchItems.length>=1);const source=searchItems.flatMap(item=>item.sources||[]).find(s=>s.material?.resourceId===resource.id);assert(source);assert.equal(source.material.offset,22);assert.equal(source.material.chunkId,chunks[22].id);assert.equal(source.material.version,resource.content_hash);assert(publicItems.some(item=>item.label==='核验资料引用'&&item.status==='completed'));
