function nativeSearchEvidence(){const result={search:[],reads:[],quotes:[]};function walk(root){for(const file of fs.readdirSync(root,{withFileTypes:true})){const full=path.join(root,file.name);if(file.isDirectory())walk(full);else if(file.name.endsWith('.jsonl'))for(const line of fs.readFileSync(full,'utf8').split('\n').filter(Boolean)){const m=JSON.parse(line).message;if(m?.role!=='toolResult')continue;for(const part of m.content||[]){if(part.type!=='text')continue;try{const v=JSON.parse(part.text);if(m.toolName==='education_search_materials'&&v.success)result.search.push({mode:v.mode,coverage:v.coverage,hits:v.hits.map(h=>({resourceId:h.resourceId,offset:h.offset,version:h.version})),truncated:v.truncated});if(m.toolName==='office_read_material'&&v.success)result.reads.push({offset:v.offset,nextOffset:v.nextOffset,version:v.source.version});if(m.toolName==='education_verify_material_quote'&&v.success)result.quotes.push({found:v.found,mode:v.mode,offset:v.offset,version:v.version});}catch{}}}}}walk(path.join(data,'xiaozhi-pi'));return result;}
function sourceButton(){return page.getByTestId('pi-web-aside').getByTestId('pi-material-source-open').filter({hasText:'第23段'}).first();}
async function openSource(source,chunkId,text){await sourceButton().waitFor({state:'visible'});await sourceButton().click();await page.getByTestId('materials-workspace').waitFor({state:'visible'});await page.getByTestId('materials-chunk-'+chunkId).getByText(text,{exact:false}).first().waitFor();assert.equal(await page.getByTestId('materials-chunk-'+chunkId).getAttribute('data-source'),'true');assert((await page.getByTestId('materials-body-location').innerText()).includes(`第 ${source.material.offset+1}`));}
