function studentRecords(studentId){const db=new DatabaseSync(path.join(data,'app.db'),{readOnly:true});try{return db.prepare('SELECT * FROM learning_records WHERE student_id=? ORDER BY created_at').all(studentId);}finally{db.close();}}
function studentNative(id){const root=path.join(data,'xiaozhi-pi',id),entries=[];function walk(dir){for(const file of fs.readdirSync(dir,{withFileTypes:true})){const full=path.join(dir,file.name);if(file.isDirectory())walk(full);else if(file.name.endsWith('.jsonl'))for(const line of fs.readFileSync(full,'utf8').split('\n').filter(Boolean))entries.push(JSON.parse(line));}}walk(root);return {entries,results:entries.filter(e=>e.message?.role==='toolResult'&&e.message.toolName==='education_read_student_context').map(e=>{try{return JSON.parse(e.message.content[0].text);}catch{return {error:e.message.content[0].text};}})};}
async function askStudent(student){await page.getByTestId('student-row-'+student.id).click();await page.getByTestId('student-ask-xiaozhi').click();await page.getByTestId('pi-student-selection').getByText(student.display_name,{exact:false}).waitFor({timeout:30000});const old=session;await until(async()=>{const id=await page.locator('.office-composer-container').getAttribute('data-session-id');if(id&&id!==old){session=id;return true;}return false;});await until(async()=>!await page.getByTestId('office-prompt-input').isDisabled());assert.equal((await snapshot()).studentContext.id,student.id);return session;}
async function recordThroughUi(student,title,content,type='mistake'){await page.getByTestId('nav-intake').click();await page.getByTestId('record-form-title').fill(title);await page.getByTestId('record-form-content').fill(content);await page.getByTestId('record-form-subject').fill('数学');await page.getByTestId('record-form-type').selectOption(type);const count=studentRecords(student.id).length;await page.getByTestId('record-form-save').click();await until(()=>studentRecords(student.id).length===count+1);await until(async()=>await page.getByTestId('record-form-title').inputValue()==='');await page.getByTestId('nav-students').click();}
async function sendStudent(text){const before=(await snapshot()).projection.turns.length,input=page.getByTestId('office-prompt-input');await input.fill(text);await input.press('Enter');assert.equal(await input.inputValue(),'');await until(async()=>{const value=await snapshot();return value.projection.turns.length>before&&!value.running;},180000);const value=await snapshot();assert.equal(value.projection.turns.at(-1).status,'completed');return value;}
