function reviewRows(){const db=new DatabaseSync(path.join(data,'app.db'),{readOnly:true});try{return db.prepare("SELECT * FROM ai_confirmation_items WHERE action_type='pi_student_learning_change' ORDER BY created_at,id").all();}finally{db.close();}}
async function proposeLearning(text){const before=reviewRows().length;const input=page.getByTestId('office-prompt-input');await input.fill(text);await input.press('Enter');assert.equal(await input.inputValue(),'');await until(()=>reviewRows().length>before,180000);const row=reviewRows().at(-1);assert.equal(row.status,'pending');const card=page.getByTestId('pi-learning-review').filter({has:page.locator(`[data-review-id="${row.id}"]`)});const actual=page.locator(`[data-testid="pi-learning-review"][data-review-id="${row.id}"]`);await actual.waitFor({state:'visible',timeout:30000});await actual.getByTestId('learning-review-reason').waitFor();return{row,card:actual};}
async function finishLearning(){await until(async()=>!(await snapshot()).running,180000);return snapshot();}
async function captureLearning(card,label){for(const theme of['light','dark'])for(const [width,height]of[[1366,768],[1920,1080]]){await page.emulateMedia({colorScheme:theme});await app.evaluate(({BrowserWindow},size)=>BrowserWindow.getAllWindows()[0].setContentSize(size.width,size.height),{width,height});await page.waitForFunction(size=>innerWidth===size.width&&innerHeight===size.height,{width,height});await card.scrollIntoViewIfNeeded();if(label==='training-edit'){await card.locator('.pi-training-calendar').evaluate(el=>el.scrollTop=0);await card.getByTestId('training-title').scrollIntoViewIfNeeded();await page.evaluate(()=>document.activeElement?.blur());}if(label==='training-approval')await card.getByTestId('learning-review-confirm').scrollIntoViewIfNeeded();if(label==='training-fields')await card.getByTestId('training-count-1').scrollIntoViewIfNeeded();const png=`${label}-${theme}-${width}x${height}.png`;await page.screenshot({path:path.join(output,png),animations:'disabled'});const geometry=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}));assert(geometry.scrollWidth<=geometry.width);report.visuals.push({png,theme,width,height,geometry});}}
